<script setup>
import {computed,ref,onMounted,watch} from 'vue'
import {useArcade} from '../stores/arcade'
import {skins} from '../data/skins'
const emit=defineEmits(['close']),s=useArcade(),dialog=ref(null),selected=ref(s.skin?.id??'default'),busy=ref(false),error=ref(''),notice=ref(''),confirm=ref(false)
const options=computed(()=>[{id:'default',name:'기본 스킨',image:s.partner.image,price:0},...skins.filter(x=>x.character===s.partner.id)]),choice=computed(()=>options.value.find(x=>x.id===selected.value)??options.value[0]),owned=computed(()=>choice.value.id==='default'||s.data.pet.ownedSkins?.includes(choice.value.id)),equipped=computed(()=>(s.skin?.id??'default')===choice.value.id)
watch(()=>s.partner.id,()=>{selected.value=s.skin?.id??'default';confirm.value=false})
onMounted(()=>dialog.value.showModal())
function select(id){if(busy.value)return;selected.value=id;confirm.value=false;error.value='';notice.value=''}
async function apply(){if(busy.value||equipped.value)return;if(!owned.value&&!confirm.value){confirm.value=true;return}busy.value=true;error.value='';try{await s.petAction('skin',choice.value.id);notice.value=choice.value.name+' 적용 완료!';confirm.value=false}catch(e){error.value=e.message}finally{busy.value=false}}
function close(){if(!busy.value){dialog.value.close();emit('close')}}
</script>
<template><dialog ref="dialog" class="skin-shop" aria-labelledby="skin-title" @cancel.prevent="close"><div class="skin-shop-heading"><div><small>SPOKEMON / SKIN COLLECTION</small><h2 id="skin-title">{{s.partner.name}} 스킨 상점</h2></div><button type="button" class="light" aria-label="스킨 상점 닫기" :disabled="busy" @click="close">✕</button></div><p class="skin-shop-note">스킨당 500 P · 구매한 스킨은 언제든 무료로 다시 적용해요.</p><div class="skin-shop-body"><div class="skin-preview"><img :src="choice.image" :alt="choice.name"/><h3>{{choice.name}}</h3><p>보유 {{s.data.coins.toLocaleString()}} P</p><p class="skin-shop-note">돌보기 화면 가운데 포켓몬에만 적용돼요. 배경·테두리·아이템창·다른 화면의 포켓몬은 그대로 유지됩니다.</p></div><div class="skin-options" aria-label="구매 가능한 스킨"><button v-for="skin in options" :key="skin.id" type="button" :class="['skin-option',{selected:selected===skin.id}]" :aria-pressed="selected===skin.id" :disabled="busy" @click="select(skin.id)"><img :src="skin.image" :alt="skin.name"/><b>{{skin.name}}</b><small>{{(s.skin?.id??'default')===skin.id?'✓ 적용 중':skin.id==='default'||s.data.pet.ownedSkins?.includes(skin.id)?'보유 · 무료 적용':'500 P'}}</small></button></div></div><div class="skin-shop-action"><p v-if="confirm" role="status">{{choice.name}} 구매에 500 P를 사용할까요? 구매 후 {{(s.data.coins-500).toLocaleString()}} P</p><button :disabled="busy||equipped||(!owned&&s.data.coins<500)" @click="apply">{{busy?'처리 중…':equipped?'✓ 적용 중':owned?'무료로 적용하기':confirm?'500 P 사용하고 구매 확정':'500 P로 구매·적용'}}</button><button v-if="confirm" class="light" :disabled="busy" @click="confirm=false">취소</button><p v-if="!owned&&s.data.coins<500">포인트가 부족해요. 퀴즈를 풀어 모아 보세요!</p><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p></div></dialog></template>
<style scoped>
.skin-shop{box-sizing:border-box;width:min(880px,calc(100vw - 24px));max-width:none;max-height:90dvh;padding:20px;overflow:auto;border:3px solid var(--rpg-edge);border-radius:18px;background:var(--rpg-paper);color:var(--rpg-ink);box-shadow:inset 0 0 0 4px var(--rpg-bright),0 8px 0 var(--rpg-shadow),0 20px 60px #0005}.skin-shop::backdrop{background:#152539b3;backdrop-filter:blur(4px)}.skin-shop-heading{display:flex;justify-content:space-between;gap:12px;align-items:center}.skin-shop-heading h2{font-size:23px;margin:6px 0}.skin-shop-heading small{font-size:10px;color:var(--rpg-edge)}.skin-shop-body{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr);gap:20px;align-items:start}.skin-preview{text-align:center;background:var(--rpg-soft);padding:12px;border:2px solid var(--rpg-mid);border-radius:12px;position:sticky;top:0}.skin-preview>img{width:100%;height:230px;object-fit:contain;background:#fff;border-radius:9px}.skin-preview h3{font-size:18px;margin:12px 0}.skin-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.skin-option{min-width:0;display:flex;flex-direction:column;align-items:stretch;gap:6px;padding:8px!important;background:var(--rpg-paper)!important;color:var(--rpg-ink)!important;border:2px solid var(--rpg-edge)!important}.skin-option.selected{background:var(--rpg-soft)!important;outline:3px solid var(--rpg-mid);outline-offset:1px}.skin-option img{width:100%;height:115px;object-fit:contain;background:#fff;border-radius:5px}.skin-option b{font-size:12px}.skin-option small{font-size:10px}.skin-shop-note{font-size:11px;line-height:1.7}.skin-shop-action{position:sticky;bottom:-20px;background:var(--rpg-paper);padding:14px 0 6px;border-top:2px solid var(--rpg-mid);margin-top:16px}.skin-shop-action p{font-size:12px}.skin-shop-action button{margin:0 8px 4px 0}.skin-shop button{touch-action:manipulation}@media(max-width:600px){.skin-shop{padding:14px;max-height:92dvh}.skin-shop-body{grid-template-columns:1fr}.skin-preview{position:static}.skin-preview>img{height:140px}.skin-preview .skin-shop-note{display:none}.skin-shop-heading h2{font-size:18px}.skin-options{grid-template-columns:repeat(2,minmax(0,1fr))}.skin-option img{height:105px}.skin-shop-action{bottom:-14px}.skin-shop-note{margin:8px 0}}
</style>
